-- Generated by scripts/generate-ecology-sql.mjs. Private JSON engine only.
-- Does not update existing rooms; adoption occurs under their normal row lock.
-- Apply only after all earlier habitat migrations have been installed.
create or replace function hash3_private.eco_config()
returns jsonb language sql immutable set search_path='' as $$ select '{"rules":{"rain":{"label":"Lluvia de bombas (antigua)","family":"legacy","effect":"demolish","distribution":"dispersed","basis":"terrain"},"cataclysm":{"label":"Cataclismo (antiguo)","family":"legacy","effect":"demolish","distribution":"local","basis":"terrain"},"meteorites":{"label":"Lluvia de meteoritos","family":"natural","effect":"demolish","distribution":"dispersed","basis":"terrain"},"earthquake":{"label":"Terremoto","family":"natural","effect":"demolish","distribution":"local","basis":"terrain"},"pandemic":{"label":"Pandemia","family":"natural","effect":"vacate","distribution":"dispersed","basis":"pieces"},"ufo":{"label":"OVNI","family":"stellar","effect":"vacate","distribution":"local","basis":"pieces"},"tornado-rain":{"label":"Lluvia de tornados","family":"natural","effect":"shuffle","distribution":"dispersed","basis":"terrain"},"hurricane":{"label":"Huracán","family":"natural","effect":"shuffle","distribution":"local","basis":"terrain"},"blackhole":{"label":"Agujero negro","family":"stellar","effect":"blackhole","distribution":"local","basis":"fixed"},"invader-rain":{"label":"Bombardeo invasor","family":"invaders","effect":"colonize","distribution":"dispersed","basis":"fixed"},"invader-colony":{"label":"Colonia invasora 3×3","family":"invaders","effect":"colonize","distribution":"local","basis":"fixed"}},"balance":{"warningMs":33000,"placementsPerAttempt":333,"invaderPlacementsPerAttempt":66,"placementScaleReference":666,"incidenceNumerator":33,"incidenceDenominator":333,"invasionRainCells":3,"invasionColonySide":3,"blackholeSide":3,"blackholeHalo":3,"dispersedTornadoSide":3,"recoveryMs":33000,"recoveryMoves":3},"naturalRotation":["meteorites","earthquake","pandemic","ufo","tornado-rain","hurricane","blackhole"],"invaderRotation":["invader-rain","invader-colony"],"minFigures":99,"frequencies":{"rodent":33,"bomb":66,"worm":33,"work":66},"weights":{"rodent":3,"bomb":1,"worm":1,"work":1},"habitatReference":333,"intervalReference":666}'::jsonb $$;

create or replace function hash3_private.eco_key(point jsonb)
returns text language sql immutable set search_path='' as $$ select (point->>'x')||','||(point->>'y') $$;
create or replace function hash3_private.eco_index(points jsonb)
returns jsonb language sql immutable set search_path='' as $$
select coalesce(jsonb_object_agg(hash3_private.eco_key(p),p),'{}') from jsonb_array_elements(coalesce(points,'[]')) p $$;
create or replace function hash3_private.eco_immune(s jsonb,owner_id text,stamp numeric)
returns boolean language sql stable set search_path='' as $$
select owner_id is not null and exists(select 1 from jsonb_array_elements(coalesce(s->'inventoryEffects'->'immunities','[]')) e where e->>'player'=owner_id and coalesce((e->>'remainingMs')::numeric,(e->>'expiresAt')::numeric-stamp,0)>0) $$;
create or replace function hash3_private.eco_protected(s jsonb,stamp numeric)
returns jsonb language sql stable set search_path='' as $$
with pieces as materialized(select hash3_private.eco_key(c) k,c from jsonb_array_elements(coalesce(s->'cells','[]')) c),
points as (
 select c from pieces where hash3_private.eco_immune(s,c->>'owner',stamp)
 union all select t from jsonb_array_elements(coalesce(s->'terrain','[]')) t left join pieces on pieces.k=hash3_private.eco_key(t) where pieces.k is null and hash3_private.eco_immune(s,t->>'owner',stamp)
 union all select c from jsonb_array_elements(coalesce(s->'frontiers','[]')) f cross join lateral jsonb_array_elements(coalesce(f->'cells','[]')) c where hash3_private.eco_immune(s,f->>'by',stamp))
select coalesce(jsonb_object_agg(hash3_private.eco_key(c),true),'{}') from points $$;

create or replace function hash3_private.eco_placements(s jsonb)
returns int language sql stable set search_path='' as $$ select coalesce(sum(coalesce((p->>'placements')::int,0)),0)::int from jsonb_array_elements(coalesce(s->'players','[]')) p $$;
create or replace function hash3_private.eco_interval(size_n int)
returns int language sql immutable set search_path='' as $$ select 3*ceil((hash3_private.eco_config()->'balance'->>'placementsPerAttempt')::numeric*greatest(size_n,(hash3_private.eco_config()->'balance'->>'placementScaleReference')::numeric)/(3*(hash3_private.eco_config()->'balance'->>'placementScaleReference')::numeric))::int $$;
create or replace function hash3_private.eco_invasion_interval(size_n int)
returns int language sql immutable set search_path='' as $$ select 3*ceil((hash3_private.eco_config()->'balance'->>'invaderPlacementsPerAttempt')::numeric*greatest(size_n,(hash3_private.eco_config()->'balance'->>'placementScaleReference')::numeric)/(3*(hash3_private.eco_config()->'balance'->>'placementScaleReference')::numeric))::int $$;
create or replace function hash3_private.eco_ready(s jsonb)
returns boolean language sql stable set search_path='' as $$ select coalesce(sum(coalesce((p->>'figures')::int,0)),0)>=(hash3_private.eco_config()->>'minFigures')::int from jsonb_array_elements(coalesce(s->'players','[]')) p $$;
create or replace function hash3_private.eco_suspended(s jsonb,stamp numeric)
returns boolean language sql stable set search_path='' as $$ select exists(select 1 from jsonb_array_elements(coalesce(s->'territoryEvents','[]')) e where hash3_private.eco_config()->'rules'->(e->>'kind')->>'family' is distinct from 'invaders') or coalesce((s->'ecologyRecovery'->>'remainingMs')::numeric,(s->'ecologyRecovery'->>'until')::numeric-stamp,0)>0 or coalesce((s->'ecologyRecovery'->>'moves')::int,0)>0 $$;

create or replace function hash3_private.eco_initialize(state jsonb,at_time timestamptz)
returns jsonb language plpgsql set search_path='' as $$
#variable_conflict use_column
declare s jsonb:=state;stamp numeric:=extract(epoch from at_time)*1000;raids jsonb:='[]';r jsonb;p jsonb;i int;
begin
 if s->>'ecologySqlVersion'='1' then return s;end if;
 for r in select v from jsonb_array_elements(coalesce(s->'rodentRaids','[]')) v loop
  raids:=raids||jsonb_build_array(r||jsonb_build_object('turn',0,'mealsLeft',coalesce((r->>'remaining')::int,3),'phase','arriving','members','[]'::jsonb));
 end loop;
 for r in select v from jsonb_array_elements(coalesce(s->'rodents','[]')) v loop
  raids:=raids||jsonb_build_array(jsonb_build_object('id',r->>'id','player',r->>'player','x',r->'x','y',r->'y','count',1,'remaining',3-least(2,coalesce((r->>'eaten')::int,0)),'mealsLeft',3-least(2,coalesce((r->>'eaten')::int,0)),'turn',0,'phase','arriving','members','[]'::jsonb,'visited','[]'::jsonb));
 end loop;
 for p,i in select v,(ord-1)::int from jsonb_array_elements(coalesce(s->'players','[]')) with ordinality a(v,ord) loop
  p:=p||jsonb_build_object('placements',coalesce((p->>'placements')::int,(select count(*)::int from jsonb_array_elements(coalesce(s->'cells','[]')) c where c->>'owner'=p->>'id')));
  s:=jsonb_set(s,array['players',i::text],p);
 end loop;
 return s||jsonb_build_object('ruleVersion',case when s->>'status'='finished' then coalesce((s->>'ruleVersion')::int,2) else 3 end,'ecologySqlVersion',1,'habitatVersion',3,'habitatFrequencyVersion',3,'rodentLifecycleVersion',1,'habitatLastCheck',stamp,'rodents','[]'::jsonb,'rodentRaids',raids,'worms',coalesce(s->'worms','[]'::jsonb),'works',coalesce(s->'works','[]'::jsonb),'bombs',coalesce(s->'bombs','[]'::jsonb),'eatenCells',coalesce(s->'eatenCells','[]'::jsonb),'habitatZones','[]'::jsonb,'territoryEvents',coalesce(s->'territoryEvents','[]'::jsonb),'territoryMilestone',jsonb_array_length(coalesce(s->'terrain','[]'))/333,'territoryNextPlacement',hash3_private.eco_placements(s)+hash3_private.eco_interval(jsonb_array_length(coalesce(s->'terrain','[]'))),'territoryNextInvasion',hash3_private.eco_placements(s)+hash3_private.eco_invasion_interval(jsonb_array_length(coalesce(s->'terrain','[]'))),'territoryActivityVersion',4,'territoryCatalogueVersion',2,'territoryKindCounter',0,'territoryNaturalIndex',0,'territoryInvasionIndex',0);
end $$;

-- Breadth-first patch. All lookups use a coordinate index prepared once.
create or replace function hash3_private.eco_cluster(pool jsonb,seed jsonb,n int,occupied jsonb default null)
returns jsonb language plpgsql set search_path='' as $$
#variable_conflict use_column
declare queue jsonb[]:=array[seed];seen jsonb:=jsonb_build_object(hash3_private.eco_key(seed),true);region jsonb:='[]';p jsonb;q jsonb;k text;dx int;dy int;i int:=1;
begin
 while i<=cardinality(queue) and jsonb_array_length(region)<n loop
  p:=queue[i];i:=i+1;
  if occupied is null or occupied ? hash3_private.eco_key(p) then region:=region||jsonb_build_array(p);end if;
  for dx,dy in select * from(values(1,0),(-1,0),(0,1),(0,-1)) d(x,y) loop
   q:=jsonb_build_object('x',(p->>'x')::int+dx,'y',(p->>'y')::int+dy);k:=hash3_private.eco_key(q);
   if pool ? k and not seen ? k then seen:=seen||jsonb_build_object(k,true);queue:=array_append(queue,pool->k);end if;
  end loop;
 end loop;
 return region;
end $$;
create or replace function hash3_private.eco_degree(region jsonb,point jsonb)
returns int language sql immutable set search_path='' as $$
select count(*)::int from (values(1,0),(-1,0),(0,1),(0,-1)) d(x,y) where region ? (((point->>'x')::int+x)::text||','||((point->>'y')::int+y)::text) $$;
create or replace function hash3_private.eco_prune(region jsonb)
returns jsonb language plpgsql set search_path='' as $$
#variable_conflict use_column
declare selected jsonb:=hash3_private.eco_index(region);old_size int;p jsonb;k text;
begin
 loop
  old_size:=(select count(*) from jsonb_each(selected));
  for k,p in select * from jsonb_each(selected) loop if hash3_private.eco_degree(selected,p)<2 then selected:=selected-k;end if;end loop;
  exit when old_size=(select count(*) from jsonb_each(selected));
 end loop;
 return coalesce((select jsonb_agg(p) from jsonb_each(selected) e(k,p)),'[]');
end $$;

create or replace function hash3_private.eco_plan(s jsonb,kind text,at_time timestamptz)
returns jsonb language plpgsql set search_path='' as $$
#variable_conflict use_column
declare cfg jsonb:=hash3_private.eco_config();rule jsonb:=cfg->'rules'->kind;balance jsonb:=cfg->'balance';stamp numeric:=extract(epoch from at_time)*1000;
 known jsonb:=hash3_private.eco_index(s->'terrain');foods jsonb:=hash3_private.eco_index(s->'cells');protected jsonb:=hash3_private.eco_protected(s,stamp);eligible jsonb:='{}';anchors jsonb;pool jsonb;region jsonb:='[]';groups jsonb:='[]';p jsonb;q jsonb;k text;target int;side int;dx int;dy int;attempt int;selected jsonb;old_size int;remaining int;
begin
 if rule is null then return jsonb_build_object('region','[]'::jsonb);end if;
 select coalesce(jsonb_object_agg(hash3_private.eco_key(coalesce(p->'terrainAnchor',p->'active')),true),'{}') into anchors from jsonb_array_elements(coalesce(s->'pairs','[]')) p;
 target:=case kind when 'invader-rain' then (balance->>'invasionRainCells')::int when 'invader-colony' then (balance->>'invasionColonySide')::int^2 when 'blackhole' then (balance->>'blackholeSide')::int^2 else floor(case when rule->>'basis'='pieces' then jsonb_array_length(s->'cells') else jsonb_array_length(s->'terrain') end*(balance->>'incidenceNumerator')::numeric/(balance->>'incidenceDenominator')::numeric)::int end;
 if kind='rain' then target:=(target/3)*3;end if;
 if target<1 then return jsonb_build_object('region','[]'::jsonb);end if;
 select coalesce(jsonb_object_agg(k,p),'{}') into eligible from jsonb_each(known) e(k,p) where (kind in ('ufo','earthquake','cataclysm') or (not protected ? k and not hash3_private.habitat_reserved(s,(p->>'x')::int,(p->>'y')::int))) and (rule->>'effect'<>'demolish' or not anchors ? k);
 if kind in ('blackhole','invader-colony') then
  side:=case kind when 'blackhole' then (balance->>'blackholeSide')::int else (balance->>'invasionColonySide')::int end;
  for p in select v from jsonb_each(eligible) e(k,v) order by random() loop
   select jsonb_agg(jsonb_build_object('x',(p->>'x')::int+x,'y',(p->>'y')::int+y)) into region from generate_series(0,side-1) x cross join generate_series(0,side-1) y;
   if (select bool_and(eligible ? hash3_private.eco_key(c)) from jsonb_array_elements(region) c) then return jsonb_build_object('region',region);end if;
  end loop;region:='[]';
 elsif kind in ('invader-rain','meteorites','rain','pandemic') then
  select coalesce(jsonb_agg(p),'[]') into region from (select v p from jsonb_each(eligible) e(k,v) where kind<>'pandemic' or foods ? k order by random() limit target) a;
 elsif kind='tornado-rain' then
  side:=(balance->>'dispersedTornadoSide')::int;pool:=eligible;remaining:=target;
  for p in select v from jsonb_each(eligible) e(k,v) order by random() loop
   exit when remaining<2;
   select coalesce(jsonb_agg(q),'[]') into region from (select eligible->(((p->>'x')::int+x)::text||','||((p->>'y')::int+y)::text) q from generate_series(0,side-1) x cross join generate_series(0,side-1) y where pool ? (((p->>'x')::int+x)::text||','||((p->>'y')::int+y)::text) limit remaining) a;
   if jsonb_array_length(region)<2 then continue;end if;
   groups:=groups||jsonb_build_array(region);remaining:=remaining-jsonb_array_length(region);
   for q in select v from jsonb_array_elements(region) v loop pool:=pool-hash3_private.eco_key(q);end loop;
  end loop;
  select coalesce(jsonb_agg(p),'[]') into region from jsonb_array_elements(groups) g cross join lateral jsonb_array_elements(g) p;
 else
  for attempt in 1..3 loop
   select v into p from jsonb_each(eligible) e(k,v) order by case when hash3_private.eco_degree(known,v)<4 then 0 else 1 end,random() limit 1;
   if p is null then exit;end if;
   region:=hash3_private.eco_cluster(eligible,p,target,case when kind='ufo' then foods else null end);
   if kind='ufo' then exit;end if;
   if kind in ('earthquake','cataclysm') then
    region:=hash3_private.eco_prune(region);selected:=hash3_private.eco_index(region);
    loop
     old_size:=(select count(*) from jsonb_each(selected));exit when old_size>=target;
     select v,k into q,k from jsonb_each(eligible) e(k,v) where not selected ? k and hash3_private.eco_degree(selected,v)>=2 limit 1;
     exit when q is null;selected:=selected||jsonb_build_object(k,q);
    end loop;
    select coalesce(jsonb_agg(v),'[]') into region from jsonb_each(selected) e(k,v);
   end if;
   exit when jsonb_array_length(region)=target;
   region:='[]';
  end loop;
 end if;
 return jsonb_build_object('region',region,'groups',groups);
end $$;

create or replace function hash3_private.eco_announce(state jsonb,at_time timestamptz,trigger_kind text)
returns jsonb language plpgsql set search_path='' as $$
#variable_conflict use_column
declare s jsonb:=state;cfg jsonb:=hash3_private.eco_config();balance jsonb:=cfg->'balance';stamp numeric:=extract(epoch from at_time)*1000;family text;rotation jsonb;idx text;offset_n int;kind text;plan jsonb;i int;k text;r jsonb;items jsonb;placements int:=hash3_private.eco_placements(s);size_n int:=jsonb_array_length(s->'terrain');
begin
 if s->>'territoryEnabled'='false' or not hash3_private.eco_ready(s) or hash3_private.eco_suspended(s,stamp) or jsonb_array_length(s->'territoryEvents')>0 then return s;end if;
 if placements>=coalesce((s->>'territoryNextPlacement')::int,2147483647) then family:='natural';s:=s||jsonb_build_object('territoryNextPlacement',placements+hash3_private.eco_interval(size_n));
 elsif placements>=coalesce((s->>'territoryNextInvasion')::int,2147483647) then family:='invaders';s:=s||jsonb_build_object('territoryNextInvasion',placements+hash3_private.eco_invasion_interval(size_n));
 else return s;end if;
 s:=s||jsonb_build_object('territoryMilestone',greatest(coalesce((s->>'territoryMilestone')::int,0),size_n/333));
 rotation:=cfg->case when family='invaders' then 'invaderRotation' else 'naturalRotation' end;
 idx:=case when family='invaders' then 'territoryInvasionIndex' else 'territoryNaturalIndex' end;
 offset_n:=coalesce((s->>idx)::int,0);s:=s||jsonb_build_object('territoryKindCounter',coalesce((s->>'territoryKindCounter')::int,0)+1,idx,offset_n+1);
 for i in 0..jsonb_array_length(rotation)-1 loop
  kind:=rotation->>((offset_n+i)%jsonb_array_length(rotation));plan:=hash3_private.eco_plan(s,kind,at_time);
  if jsonb_array_length(plan->'region')=0 then continue;end if;
  if family<>'invaders' then
   foreach k in array array['worms','works','bombs'] loop
    select coalesce(jsonb_agg(v||jsonb_build_object('remainingMs',coalesce((v->>'remainingMs')::numeric,greatest(0,(v->>'nextAt')::numeric-stamp)))),'[]') into items from jsonb_array_elements(s->k) v;s:=jsonb_set(s,array[k],items);
   end loop;
  end if;
  r:=plan||jsonb_build_object('id',gen_random_uuid(),'kind',kind,'milestone',s->'territoryMilestone','trigger',trigger_kind,'x',plan->'region'->0->'x','y',plan->'region'->0->'y','nextAt',stamp+(balance->>'warningMs')::numeric);
  return jsonb_set(s,'{territoryEvents}',jsonb_build_array(r));
 end loop;
 return s;
end $$;

create or replace function hash3_private.eco_shuffle(state jsonb,points jsonb,stamp numeric)
returns jsonb language plpgsql set search_path='' as $$
#variable_conflict use_column
declare s jsonb:=state;known jsonb:=hash3_private.eco_index(s->'terrain');protected jsonb:=hash3_private.eco_protected(s,stamp);slots jsonb;pieces jsonb;index jsonb:=hash3_private.eco_index(s->'cells');hit jsonb;p jsonb;i int;
begin
 select coalesce(jsonb_agg(c),'[]') into slots from jsonb_array_elements(points) c where known ? hash3_private.eco_key(c) and not protected ? hash3_private.eco_key(c) and not hash3_private.habitat_reserved(s,(c->>'x')::int,(c->>'y')::int);
 if jsonb_array_length(slots)<2 then return s;end if;hit:=hash3_private.eco_index(slots);
 select jsonb_agg(v order by random()) into pieces from (select coalesce(index->hash3_private.eco_key(c),'null'::jsonb) v from jsonb_array_elements(slots) c) a;
 s:=jsonb_set(s,'{cells}',(select coalesce(jsonb_agg(c),'[]') from jsonb_array_elements(s->'cells') c where not hit ? hash3_private.eco_key(c)));
 for i in 0..jsonb_array_length(slots)-1 loop
  p:=pieces->i;if p='null'::jsonb then continue;end if;
  s:=jsonb_set(s,'{cells}',(s->'cells')||jsonb_build_array(p||jsonb_build_object('x',slots->i->'x','y',slots->i->'y')));
 end loop;return s;
end $$;

create or replace function hash3_private.eco_apply(state jsonb,event jsonb,at_time timestamptz)
returns jsonb language plpgsql set search_path='' as $$
#variable_conflict use_column
declare s jsonb:=state;cfg jsonb:=hash3_private.eco_config();rule jsonb:=cfg->'rules'->(event->>'kind');kind text:=event->>'kind';effect text:=rule->>'effect';stamp numeric:=extract(epoch from at_time)*1000;protected jsonb:=hash3_private.eco_protected(s,stamp);known jsonb:=hash3_private.eco_index(s->'terrain');hit jsonb;region jsonb;halo jsonb;actions jsonb:='[]';c jsonb;p jsonb;i int;survivor jsonb;core jsonb:=event->'region';x0 int;x1 int;y0 int;y1 int;distance_n int:=(cfg->'balance'->>'blackholeHalo')::int;
begin
 if effect is null then return s;end if;
 if effect='demolish' then for p in select v from jsonb_array_elements(s->'pairs') v loop protected:=protected||jsonb_build_object(hash3_private.eco_key(coalesce(p->'terrainAnchor',p->'active')),true);end loop;end if;
 select coalesce(jsonb_agg(c),'[]') into region from jsonb_array_elements(core) c where known ? hash3_private.eco_key(c) and not protected ? hash3_private.eco_key(c) and not hash3_private.habitat_reserved(s,(c->>'x')::int,(c->>'y')::int);
 if kind in ('earthquake','cataclysm') then region:=hash3_private.eco_prune(region);end if;
 hit:=hash3_private.eco_index(region);
 if effect='shuffle' then
  if kind='tornado-rain' and jsonb_array_length(coalesce(event->'groups','[]'))>0 then
   for p in select v from jsonb_array_elements(event->'groups') v loop s:=hash3_private.eco_shuffle(s,p,stamp);end loop;
  else s:=hash3_private.eco_shuffle(s,region,stamp);end if;
 else
  s:=jsonb_set(s,'{cells}',(select coalesce(jsonb_agg(c),'[]') from jsonb_array_elements(s->'cells') c where not hit ? hash3_private.eco_key(c)));
  if effect='colonize' then
   for c in select v from jsonb_array_elements(region) v loop s:=jsonb_set(s,'{cells}',(s->'cells')||jsonb_build_array(c||jsonb_build_object('id',gen_random_uuid(),'symbol','*','owner',null,'invader',true)));end loop;
  elsif effect='blackhole' and jsonb_array_length(core)>0 then
   select min((c->>'x')::int),max((c->>'x')::int),min((c->>'y')::int),max((c->>'y')::int) into x0,x1,y0,y1 from jsonb_array_elements(core) c;
   select coalesce(jsonb_agg(c),'[]') into halo from jsonb_array_elements(s->'terrain') c where not hit ? hash3_private.eco_key(c) and not protected ? hash3_private.eco_key(c) and not hash3_private.habitat_reserved(s,(c->>'x')::int,(c->>'y')::int) and (c->>'x')::int between x0-distance_n and x1+distance_n and (c->>'y')::int between y0-distance_n and y1+distance_n;
   s:=hash3_private.eco_shuffle(s,halo,stamp);region:=region||halo;hit:=hash3_private.eco_index(region);
  end if;
 end if;
 s:=jsonb_set(s,'{forms}',(select coalesce(jsonb_agg(f),'[]') from jsonb_array_elements_text(coalesce(s->'forms','[]')) f where not exists(select 1 from unnest(string_to_array(split_part(f,':',3),';')) coordinate where hit ? coordinate)));
 for p,i in select v,(ord-1)::int from jsonb_array_elements(s->'players') with ordinality a(v,ord) loop
  if p ? 'lastMove' then select c into survivor from jsonb_array_elements(s->'cells') c where c->>'id'=p->'lastMove'->>'id';p:=p-'lastMove';if survivor is not null then p:=p||jsonb_build_object('lastMove',survivor);end if;s:=jsonb_set(s,array['players',i::text],p);end if;
 end loop;
 s:=jsonb_set(s,'{eatenCells}',(select coalesce(jsonb_agg(c),'[]') from jsonb_array_elements(s->'eatenCells') c where not hit ? hash3_private.eco_key(c)));
 if effect in ('vacate','blackhole') then
  s:=jsonb_set(s,'{eatenCells}',(s->'eatenCells')||(select coalesce(jsonb_agg(c),'[]') from jsonb_array_elements(case when effect='blackhole' then core else region end) c where not exists(select 1 from jsonb_array_elements(s->'cells') p where hash3_private.eco_key(p)=hash3_private.eco_key(c))));
 end if;
 if effect='demolish' then
  s:=jsonb_set(s,'{terrain}',(select coalesce(jsonb_agg(c),'[]') from jsonb_array_elements(s->'terrain') c where not hit ? hash3_private.eco_key(c)));
  s:=jsonb_set(s,'{frontiers}',(select coalesce(jsonb_agg(f),'[]') from jsonb_array_elements(coalesce(s->'frontiers','[]')) f where hash3_private.eco_immune(s,f->>'by',stamp) or not exists(select 1 from jsonb_array_elements(coalesce(f->'cells','[]')||(select coalesce(jsonb_agg(e->'a')||jsonb_agg(e->'b'),'[]') from jsonb_array_elements(coalesce(f->'edges','[]')) e)) c where hit ? hash3_private.eco_key(c))));
  s:=jsonb_set(s,'{worms}',(select coalesce(jsonb_agg(w),'[]') from jsonb_array_elements(s->'worms') w where not exists(select 1 from jsonb_array_elements(coalesce(w->'body','[]')) c where hit ? hash3_private.eco_key(c))));
  s:=jsonb_set(s,'{works}',(select coalesce(jsonb_agg(w),'[]') from jsonb_array_elements(s->'works') w where not exists(select 1 from jsonb_array_elements((w->'destroy')||(w->'build')) with ordinality a(c,ord) where (ord-1)::int%3>=coalesce((w->>'done')::int,0) and hit ? hash3_private.eco_key(c))));
  s:=jsonb_set(s,'{bombs}',(select coalesce(jsonb_agg(w),'[]') from jsonb_array_elements(s->'bombs') w where not exists(select 1 from jsonb_array_elements(w->'blast') c where hit ? hash3_private.eco_key(c))));
  s:=jsonb_set(s,'{rodentRaids}',(select coalesce(jsonb_agg(r),'[]') from jsonb_array_elements(s->'rodentRaids') r where not hit ? hash3_private.eco_key(r)));
 end if;
 if s ? 'inventoryEffects' then
  s:=jsonb_set(s,'{inventoryEffects,shields}',(select coalesce(jsonb_agg(e),'[]') from jsonb_array_elements(coalesce(s->'inventoryEffects'->'shields','[]')) e where exists(select 1 from jsonb_array_elements(s->'cells') c where c->>'id'=e->>'cell') and not exists(select 1 from jsonb_array_elements(state->'cells') c where c->>'id'=e->>'cell' and hit ? hash3_private.eco_key(c))));
  s:=jsonb_set(s,'{inventoryEffects,blocks}',(select coalesce(jsonb_agg(e),'[]') from jsonb_array_elements(coalesce(s->'inventoryEffects'->'blocks','[]')) e where not hit ? hash3_private.eco_key(e)));
 end if;
 select coalesce(jsonb_agg(c||jsonb_build_object('kind',kind)),'[]') into actions from jsonb_array_elements(region) c;
 return s||jsonb_build_object('habitatEvent',jsonb_build_object('id',gen_random_uuid(),'kind','habitat','at',stamp,'actions',actions));
end $$;

create or replace function hash3_private.eco_rebalance(state jsonb,at_time timestamptz)
returns jsonb language plpgsql set search_path='' as $$
#variable_conflict use_column
declare s jsonb:=state;stamp numeric:=extract(epoch from at_time)*1000;cfg jsonb:=hash3_private.eco_config();size_n int:=jsonb_array_length(s->'terrain');known jsonb:=hash3_private.eco_index(s->'terrain');unit int:=ceil(size_n/333.0);rats int:=ceil(size_n*3/333.0);r jsonb;raids jsonb:='[]';count_n int;zones jsonb:='[]';z jsonb;nexts jsonb;k text;f int;
begin
 select coalesce(jsonb_agg(w),'[]') into r from (select v w from jsonb_array_elements(s->'worms') v where not exists(select 1 from jsonb_array_elements(v->'body') c where not known ? hash3_private.eco_key(c)) limit unit) a;s:=jsonb_set(s,'{worms}',r);
 select coalesce(jsonb_agg(w),'[]') into r from (select v w from jsonb_array_elements(s->'works') v where not exists(select 1 from jsonb_array_elements(v->'destroy') with ordinality a(c,ord) where ord>(v->>'done')::int and not known ? hash3_private.eco_key(c)) limit unit*3) a;s:=jsonb_set(s,'{works}',r);
 for r in select v from jsonb_array_elements(s->'rodentRaids') v where known ? hash3_private.eco_key(v) loop
  count_n:=least(rats,(r->>'count')::int);rats:=rats-count_n;
  if count_n>0 then raids:=raids||jsonb_build_array(r||jsonb_build_object('count',count_n,'members',(select coalesce(jsonb_agg(c),'[]') from jsonb_array_elements(coalesce(r->'members','[]')) with ordinality a(c,ord) where ord<=count_n)));end if;
 end loop;s:=jsonb_set(s,'{rodentRaids}',raids);
 for z in select v from jsonb_array_elements(s->'habitatZones') v loop
  nexts:='{}';for k,f in select key,value::int from jsonb_each_text(cfg->'frequencies') loop nexts:=nexts||jsonb_build_object(k,(z->>'placements')::int+ceil(f*greatest(1,size_n/(cfg->>'intervalReference')::numeric))::int);end loop;
  zones:=zones||jsonb_build_array(z||jsonb_build_object('credit','{}'::jsonb,'next',nexts));
 end loop;s:=jsonb_set(s,'{habitatZones}',zones);
 foreach k in array array['worms','works','bombs'] loop
  s:=jsonb_set(s,array[k],(select coalesce(jsonb_agg(v||jsonb_build_object('remainingMs',(cfg->'balance'->>'recoveryMs')::int)),'[]') from jsonb_array_elements(s->k) v));
 end loop;
 return s||jsonb_build_object('ecologyRecovery',jsonb_build_object('until',stamp+(cfg->'balance'->>'recoveryMs')::numeric,'moves',(cfg->'balance'->>'recoveryMoves')::int));
end $$;

create or replace function hash3_private.eco_events_advance(state jsonb,at_time timestamptz)
returns jsonb language plpgsql set search_path='' as $$
#variable_conflict use_column
declare s jsonb:=state;e jsonb;remaining jsonb:='[]';stamp numeric:=extract(epoch from at_time)*1000;gap numeric:=stamp-coalesce((s->>'habitatLastCheck')::numeric,stamp);point jsonb;
begin
 if s->>'status'<>'playing' or s->>'territoryEnabled'='false' then return s;end if;
 for e in select v from jsonb_array_elements(s->'territoryEvents') v loop
  point:=e->'region'->0;
  if not hash3_private.habitat_active(s,point) then e:=e||jsonb_build_object('remainingMs',coalesce((e->>'remainingMs')::numeric,greatest(0,(e->>'nextAt')::numeric-coalesce((s->>'habitatLastCheck')::numeric,stamp))));
  elsif e ? 'remainingMs' then e:=(e-'remainingMs')||jsonb_build_object('nextAt',stamp+(e->>'remainingMs')::numeric);
  elsif gap>10000 then e:=e||jsonb_build_object('nextAt',(e->>'nextAt')::numeric+gap);
  elsif (e->>'nextAt')::numeric<=stamp then
   s:=hash3_private.eco_apply(s,e,at_time);if hash3_private.eco_config()->'rules'->(e->>'kind')->>'family' is distinct from 'invaders' then s:=hash3_private.eco_rebalance(s,at_time);end if;continue;
  end if;
  remaining:=remaining||jsonb_build_array(e);
 end loop;
 return jsonb_set(s,'{territoryEvents}',remaining);
end $$;

create or replace function hash3_private.habitat_initialize(state jsonb,at_time timestamptz)
returns jsonb language sql set search_path='' as $$ select hash3_private.eco_initialize(state,at_time) $$;

create or replace function hash3_private.habitat_freeze(state jsonb,at_time timestamptz,resume boolean default false)
returns jsonb language plpgsql set search_path='' as $$
#variable_conflict use_column
declare s jsonb:=hash3_private.eco_initialize(state,at_time);k text;items jsonb;stamp numeric:=extract(epoch from at_time)*1000;
begin
 foreach k in array array['worms','works','bombs','territoryEvents'] loop
  select coalesce(jsonb_agg(case when resume then (v-'remainingMs')||jsonb_build_object('nextAt',stamp+coalesce((v->>'remainingMs')::numeric,33000)) else v||jsonb_build_object('remainingMs',coalesce((v->>'remainingMs')::numeric,greatest(0,(v->>'nextAt')::numeric-stamp))) end),'[]') into items from jsonb_array_elements(s->k) v;s:=jsonb_set(s,array[k],items);
 end loop;
 if s ? 'ecologyRecovery' then
  if resume then s:=jsonb_set(s,'{ecologyRecovery}',((s->'ecologyRecovery')-'remainingMs')||jsonb_build_object('until',stamp+coalesce((s->'ecologyRecovery'->>'remainingMs')::numeric,33000)));
  else s:=jsonb_set(s,'{ecologyRecovery}',s->'ecologyRecovery'||jsonb_build_object('remainingMs',coalesce((s->'ecologyRecovery'->>'remainingMs')::numeric,greatest(0,(s->'ecologyRecovery'->>'until')::numeric-stamp))));end if;
 end if;
 if s ? 'inventoryEffects' then
  s:=jsonb_set(s,'{inventoryEffects,immunities}',(select coalesce(jsonb_agg(case when resume then (v-'remainingMs')||jsonb_build_object('expiresAt',stamp+coalesce((v->>'remainingMs')::numeric,33000)) else v||jsonb_build_object('remainingMs',greatest(0,(v->>'expiresAt')::numeric-stamp)) end),'[]') from jsonb_array_elements(coalesce(s->'inventoryEffects'->'immunities','[]')) v));
 end if;
 return s||jsonb_build_object('habitatLastCheck',stamp);
end $$;

create or replace function hash3_private.habitat_occupied(s jsonb,point jsonb,excluded text default null)
returns boolean language sql stable set search_path='' as $$
select exists(select 1 from jsonb_array_elements(coalesce(s->'works','[]')) w cross join lateral jsonb_array_elements((w->'destroy')||(w->'build')) with ordinality a(c,ord) where (ord-1)::int%3>=coalesce((w->>'done')::int,0) and hash3_private.eco_key(c)=hash3_private.eco_key(point))
or exists(select 1 from jsonb_array_elements(coalesce(s->'worms','[]')) w cross join lateral jsonb_array_elements(w->'body') c where w->>'id' is distinct from excluded and hash3_private.eco_key(c)=hash3_private.eco_key(point))
or exists(select 1 from jsonb_array_elements(coalesce(s->'rodentRaids','[]')) r cross join lateral jsonb_array_elements(coalesce(r->'members','[]')) c where r->>'id' is distinct from excluded and r->>'phase'<>'hidden' and hash3_private.eco_key(c)=hash3_private.eco_key(point)) $$;

-- Extend the already-tested timed worm/work engine, retaining its no-catch-up
-- handling and room locking. Refuse an unexpected baseline rather than patching it silently.
DO $adapt_timed$
declare definition text;
begin
 select pg_get_functiondef('hash3_private.habitat_advance(jsonb,timestamptz)'::regprocedure) into definition;
 if position('eco_events_advance' in definition)=0 then
  if position($needle$if s->>'status'<>'playing' then return s;end if;$needle$ in definition)=0 then raise exception 'Unexpected habitat_advance baseline';end if;
  definition:=replace(definition,$needle$if s->>'status'<>'playing' then return s;end if;$needle$,$body$
if s->>'status'<>'playing' then return s;end if;
s:=hash3_private.eco_events_advance(s,at_time);
if s->'habitatEvent'->'id' is distinct from state->'habitatEvent'->'id' then actions:=coalesce(s->'habitatEvent'->'actions','[]');end if;
if s->'territoryEvents' is distinct from state->'territoryEvents' or s->'cells' is distinct from state->'cells' then changed:=true;end if;
if hash3_private.eco_suspended(s,stamp) or s->>'ecoSuppressFauna'='true' or s->>'faunaEnabled'='false' then
 if changed then s:=s||jsonb_build_object('version',coalesce((s->>'version')::int,0)+1);end if;
 return s||jsonb_build_object('habitatLastCheck',stamp);
end if;
s:=s-'ecologyRecovery';$body$);
  definition:=replace(definition,$needle$if kind='works' then
n:=(r->>'done')::int;add_point:=r->'build'->n;$needle$,$body$if kind='works' then
n:=(r->>'done')::int;add_point:=r->'build'->n;
if hash3_private.eco_protected(s,stamp) ? hash3_private.eco_key(point) then all_events:=all_events||jsonb_build_array(r);continue;end if;$body$);
  definition:=replace(definition,$needle$where c->>'x'=r->>'x' and c->>'y'=r->>'y';$needle$,$body$where c->>'x'=r->>'x' and c->>'y'=r->>'y' and not hash3_private.eco_immune(s,c->>'owner',stamp);$body$);
  execute definition;
 end if;
 select pg_get_functiondef('hash3_private.habitat_food(jsonb,jsonb,boolean,text)'::regprocedure) into definition;
 if position('eco_immune' in definition)=0 then
  definition:=replace(definition,$needle$where c->>'id' is distinct from excluded$needle$,$body$where not hash3_private.eco_immune(s,c->>'owner',extract(epoch from now())*1000) and c->>'id' is distinct from excluded$body$);execute definition;
 end if;
end $adapt_timed$;

-- Guarded revocations: helpers are never a client-writable alternative to RPC.
create or replace function hash3_private.habitat_project(state jsonb,point jsonb,actor text,at_time timestamptz)
returns jsonb language plpgsql set search_path='' as $$
#variable_conflict use_column
declare s jsonb:=state;area jsonb:=hash3_private.habitat_area(s,point);known jsonb:=hash3_private.eco_index(s->'terrain');pieces jsonb:=hash3_private.eco_index(s->'cells');eligible jsonb:='{}';protected jsonb:=hash3_private.eco_protected(s,extract(epoch from at_time)*1000);anchors jsonb;destroy jsonb:='[]';build jsonb:='[]';block jsonb;p jsonb;q jsonb;k text;origins jsonb:='{}';boundary jsonb:='{}';dx int;dy int;i int;stamp numeric:=extract(epoch from at_time)*1000;
begin
 select coalesce(jsonb_object_agg(hash3_private.eco_key(coalesce(v->'terrainAnchor',v->'active')),true),'{}') into anchors from jsonb_array_elements(s->'pairs') v;
 for p in select v from jsonb_array_elements(area) v loop
  k:=hash3_private.eco_key(p);
  if not pieces ? k and not anchors ? k and not protected ? k and not hash3_private.habitat_occupied(s,p) then eligible:=eligible||jsonb_build_object(k,p);end if;
  for dx,dy in select * from(values(1,0),(-1,0),(0,1),(0,-1)) d(x,y) loop
   q:=jsonb_build_object('x',(p->>'x')::int+dx,'y',(p->>'y')::int+dy);
   if not known ? hash3_private.eco_key(q) and not hash3_private.habitat_reserved(s,(q->>'x')::int,(q->>'y')::int) and not hash3_private.habitat_edge_blocked(s,(p->>'x')::int,(p->>'y')::int,(q->>'x')::int,(q->>'y')::int) then boundary:=boundary||jsonb_build_object(hash3_private.eco_key(q),q);end if;
  end loop;
 end loop;
 for p in select v from jsonb_each(eligible) e(k,v) order by random() loop
  select jsonb_agg(jsonb_build_object('x',(p->>'x')::int+x,'y',(p->>'y')::int+y)) into block from generate_series(0,2) x cross join generate_series(0,2) y;
  if (select bool_and(eligible ? hash3_private.eco_key(c)) from jsonb_array_elements(block) c) then destroy:=block;exit;end if;
 end loop;
 if jsonb_array_length(destroy)=0 then
  for p in select v from jsonb_each(eligible) e(k,v) order by random() loop
   block:=hash3_private.eco_cluster(eligible,p,9);if jsonb_array_length(block)=9 then destroy:=block;exit;end if;
  end loop;
 end if;if jsonb_array_length(destroy)<>9 then return s;end if;
 for p in select v from jsonb_each(boundary) e(k,v) loop
  for dx in 0..2 loop for dy in 0..2 loop
   q:=jsonb_build_object('x',(p->>'x')::int-dx,'y',(p->>'y')::int-dy);origins:=origins||jsonb_build_object(hash3_private.eco_key(q),q);
  end loop;end loop;
 end loop;
 for p in select v from jsonb_each(origins) e(k,v) order by random() loop
  select jsonb_agg(jsonb_build_object('x',(p->>'x')::int+x,'y',(p->>'y')::int+y)) into block from generate_series(0,2) x cross join generate_series(0,2) y;
  if (select bool_and(not known ? hash3_private.eco_key(c) and not hash3_private.habitat_reserved(s,(c->>'x')::int,(c->>'y')::int) and not exists(select 1 from jsonb_array_elements(coalesce(s->'frontiers','[]')) f cross join lateral jsonb_array_elements(coalesce(f->'cells','[]')) wall where hash3_private.eco_key(wall)=hash3_private.eco_key(c))) from jsonb_array_elements(block) c) then build:=block;exit;end if;
 end loop;
 if jsonb_array_length(build)=0 then
  select v into p from jsonb_each(boundary) e(k,v) order by random() limit 1;
  if p is null then return s;end if;build:=jsonb_build_array(p);
  for i in 1..8 loop
   select candidate into q from (select distinct jsonb_build_object('x',(c->>'x')::int+d.x,'y',(c->>'y')::int+d.y) candidate from jsonb_array_elements(build) c cross join (values(1,0),(-1,0),(0,1),(0,-1)) d(x,y)) options
   where not known ? hash3_private.eco_key(candidate) and not hash3_private.eco_index(build) ? hash3_private.eco_key(candidate) and not hash3_private.habitat_reserved(s,(candidate->>'x')::int,(candidate->>'y')::int) order by random() limit 1;
   if q is null then return s;end if;build:=build||jsonb_build_array(q);
  end loop;
 end if;
 for i in 0..2 loop
  s:=jsonb_set(s,'{works}',(s->'works')||jsonb_build_array(jsonb_build_object('id',gen_random_uuid(),'player',actor,'kind','work','destroy',(select jsonb_agg(c order by ord) from jsonb_array_elements(destroy) with ordinality a(c,ord) where ord between i*3+1 and i*3+3),'build',(select jsonb_agg(c order by ord) from jsonb_array_elements(build) with ordinality a(c,ord) where ord between i*3+1 and i*3+3),'done',0,'nextAt',stamp+33000)));
 end loop;return s;
end $$;

create or replace function hash3_private.eco_position_rodents(s jsonb,raid jsonb,point jsonb)
returns jsonb language plpgsql set search_path='' as $$
#variable_conflict use_column
declare r jsonb:=raid;area jsonb:=hash3_private.eco_index(hash3_private.habitat_area(s,r));visited jsonb:=hash3_private.eco_index(r->'visited');taken jsonb:='{}';c jsonb;i int;members jsonb:='[]';stamp numeric:=extract(epoch from now())*1000;
begin
 for i in 0..(r->>'count')::int-1 loop
  select v into c from jsonb_array_elements(s->'cells') v where area ? hash3_private.eco_key(v) and not visited ? hash3_private.eco_key(v) and not taken ? hash3_private.eco_key(v) and hash3_private.eco_key(v)<>hash3_private.eco_key(point) and v->>'symbol' in ('X','O') and not hash3_private.eco_immune(s,v->>'owner',stamp) and not hash3_private.habitat_occupied(s,v,r->>'id') order by random() limit 1;
  if c is null then select v into c from jsonb_each(area) e(k,v) where not visited ? k and not taken ? k and k<>hash3_private.eco_key(point) and not hash3_private.eco_index(s->'cells') ? k and not hash3_private.habitat_occupied(s,v,r->>'id') order by random() limit 1;end if;
  exit when c is null;taken:=taken||jsonb_build_object(hash3_private.eco_key(c),true);members:=members||jsonb_build_array(jsonb_build_object('id',(r->>'id')||':'||i,'x',c->'x','y',c->'y','cellId',c->'id'));
 end loop;return r||jsonb_build_object('members',members);
end $$;

create or replace function hash3_private.eco_visit_rodents(state jsonb,point jsonb,at_time timestamptz)
returns jsonb language plpgsql set search_path='' as $$
#variable_conflict use_column
declare s jsonb:=state;area jsonb:=hash3_private.eco_index(hash3_private.habitat_area(s,point));r jsonb;c jsonb;m jsonb;raids jsonb:='[]';visits jsonb:='[]';stamp numeric:=extract(epoch from at_time)*1000;turn_n int;stage int;
begin
 for r in select v from jsonb_array_elements(s->'rodentRaids') v loop
  if area ? hash3_private.eco_key(r) then
   turn_n:=coalesce((r->>'turn')::int,0)+1;stage:=(turn_n-1)%3;r:=r||jsonb_build_object('turn',turn_n,'phaseAt',stamp);
   if stage=0 then r:=r||jsonb_build_object('phase','arriving');if jsonb_array_length(coalesce(r->'members','[]'))=0 then r:=hash3_private.eco_position_rodents(s,r,point);end if;
   elsif stage=1 then
    r:=r||jsonb_build_object('phase','eating');
    for m in select v from jsonb_array_elements(r->'members') v loop
     select v into c from jsonb_array_elements(s->'cells') v where v->>'id'=m->>'cellId' and hash3_private.eco_key(v)=hash3_private.eco_key(m) and hash3_private.eco_key(v)<>hash3_private.eco_key(point) and v->>'symbol' in ('X','O') and not hash3_private.eco_immune(s,v->>'owner',stamp) and not hash3_private.habitat_occupied(s,v,r->>'id');
     if c is not null then visits:=visits||jsonb_build_array(c||jsonb_build_object('cellId',c->>'id'));s:=hash3_private.habitat_clear(s,c);end if;
     r:=jsonb_set(r,'{visited}',coalesce(r->'visited','[]'::jsonb)||jsonb_build_array(jsonb_build_object('x',m->'x','y',m->'y')));
    end loop;
   else r:=r||jsonb_build_object('phase','hidden','members','[]'::jsonb,'mealsLeft',coalesce((r->>'mealsLeft')::int,(r->>'remaining')::int,3)-1);end if;
   r:=r||jsonb_build_object('remaining',coalesce((r->>'mealsLeft')::int,3));
  end if;
  if (r->>'remaining')::int>0 then raids:=raids||jsonb_build_array(r);end if;
 end loop;
 if jsonb_array_length(visits)>0 then s:=s||jsonb_build_object('rodentVisit',jsonb_build_object('id',gen_random_uuid(),'kind','rodent','at',stamp,'visits',visits));end if;
 return jsonb_set(s,'{rodentRaids}',raids);
end $$;

-- Each accepted placement updates the shared reachable-zone budget once.
create or replace function hash3_private.rodent_step(state jsonb,actor text)
returns jsonb language plpgsql set search_path='' as $$
#variable_conflict use_column
declare s jsonb:=hash3_private.eco_initialize(state,now());cfg jsonb:=hash3_private.eco_config();stamp numeric:=extract(epoch from now())*1000;e jsonb:=s->'lastEvent';p jsonb;pi int;point jsonb;area jsonb;known jsonb;z jsonb;matching jsonb;zones jsonb;nexts jsonb:='{}';credit jsonb:='{}';k text;f int;interval_n int;n int;size_n int;count_n int;capacity int;residents numeric;budget numeric;r jsonb;c jsonb;i int;was_suspended boolean:=hash3_private.eco_suspended(s,stamp);
begin
 if e->>'kind' is distinct from 'move' or s->>'rodentEvent'=e->>'id' then return s;end if;
 select v,(ord-1)::int into p,pi from jsonb_array_elements(s->'players') with ordinality a(v,ord) where v->>'id'=actor;
 select v into point from jsonb_array_elements(s->'cells') v where v->>'id'=e->>'id';if p is null or point is null then return s;end if;
 area:=hash3_private.habitat_area(s,point);size_n:=jsonb_array_length(area);known:=hash3_private.eco_index(area);
 select coalesce(jsonb_agg(v),'[]') into matching from jsonb_array_elements(s->'habitatZones') v where known ? hash3_private.eco_key(v);
 if jsonb_array_length(matching)=1 then z:=matching->0;
 else
  n:=coalesce((select sum((v->>'placements')::int)::int from jsonb_array_elements(matching) v),(select sum(coalesce((v->>'placements')::int,0))::int from jsonb_array_elements(s->'players') v join jsonb_array_elements(s->'pairs') pair on pair->>'id'=v->>'pair' where known ? hash3_private.eco_key(coalesce(pair->'terrainAnchor',pair->'active'))),0);
  for k,f in select key,value::int from jsonb_each_text(cfg->'frequencies') loop
   interval_n:=ceil(f*greatest(1,size_n/(cfg->>'intervalReference')::numeric));nexts:=nexts||jsonb_build_object(k,(n/interval_n+1)*interval_n);credit:=credit||jsonb_build_object(k,coalesce((select sum((v->'credit'->>k)::numeric)%1 from jsonb_array_elements(matching) v),0));
  end loop;
  z:=jsonb_build_object('id',gen_random_uuid(),'x',area->0->'x','y',area->0->'y','placements',n,'next',nexts,'credit',credit);
 end if;
 n:=coalesce((p->>'placements')::int,0)+1;p:=p||jsonb_build_object('placements',n);s:=jsonb_set(s,array['players',pi::text],p);z:=z||jsonb_build_object('placements',(z->>'placements')::int+1);
 s:=s||jsonb_build_object('rodentEvent',e->>'id');
 if (s->'ecologyRecovery'->>'moves')::int>0 then s:=jsonb_set(s,'{ecologyRecovery,moves}',to_jsonb((s->'ecologyRecovery'->>'moves')::int-1));end if;
 s:=hash3_private.eco_announce(s,now(),'placements');
 if not was_suspended and not hash3_private.eco_suspended(s,stamp) and s->>'faunaEnabled' is distinct from 'false' then
  s:=hash3_private.eco_visit_rodents(s,point,now());
  for k,f in select key,value::int from jsonb_each_text(cfg->'frequencies') order by case key when 'rodent' then 0 when 'worm' then 1 else 2 end loop
   if k='bomb' or (z->>'placements')::int<(z->'next'->>k)::int then continue;end if;
   interval_n:=ceil(f*greatest(1,size_n/(cfg->>'intervalReference')::numeric));z:=jsonb_set(z,array['next',k],to_jsonb((z->>'placements')::int+interval_n));
   budget:=coalesce((z->'credit'->>k)::numeric,0)+size_n/(cfg->>'habitatReference')::numeric*(cfg->'weights'->>k)::numeric;
   count_n:=floor(budget+0.000000001);z:=jsonb_set(z,array['credit',k],to_jsonb(greatest(0,budget-count_n)));capacity:=ceil(size_n/(cfg->>'habitatReference')::numeric*(cfg->'weights'->>k)::numeric);
   if k='rodent' then select coalesce(sum((r->>'count')::int),0) into residents from jsonb_array_elements(s->'rodentRaids') r where known ? hash3_private.eco_key(r);
   elsif k='work' then select count(*)/3.0 into residents from jsonb_array_elements(s->'works') w where known ? hash3_private.eco_key(w->'destroy'->((w->>'done')::int));
   else select count(*) into residents from jsonb_array_elements(s->'worms') w where known ? hash3_private.eco_key(w);end if;
   count_n:=greatest(0,least(count_n,floor(capacity-residents)::int));
   if k='rodent' and count_n>0 then
    r:=point||jsonb_build_object('id',gen_random_uuid(),'player',actor,'count',count_n,'remaining',3,'mealsLeft',3,'turn',0,'phase','arriving','phaseAt',stamp,'visited','[]'::jsonb,'members','[]'::jsonb);r:=hash3_private.eco_position_rodents(s,r,point);s:=jsonb_set(s,'{rodentRaids}',(s->'rodentRaids')||jsonb_build_array(r));
   elsif k='work' then for i in 1..count_n loop s:=hash3_private.habitat_project(s,point,actor,now());end loop;
   elsif k='worm' then for i in 1..count_n loop
    r:=jsonb_build_object('id',gen_random_uuid(),'kind','worm','player',actor,'x',point->'x','y',point->'y','eaten',0,'phase',0,'nextAt',stamp+33000);c:=hash3_private.habitat_food(s,r,false,point->>'id');
    if c is not null then r:=r||jsonb_build_object('x',c->'x','y',c->'y','body',jsonb_build_array(jsonb_build_object('x',c->'x','y',c->'y')));s:=jsonb_set(s,'{worms}',(s->'worms')||jsonb_build_array(r));end if;
   end loop;end if;
  end loop;
 end if;
 if not was_suspended and not hash3_private.eco_suspended(s,stamp) and s->>'territoryEnabled' is distinct from 'false' and n%33=0 then s:=hash3_private.territory_neutral(s,point);end if;
 select coalesce(jsonb_agg(v),'[]') into zones from jsonb_array_elements(s->'habitatZones') v where not known ? hash3_private.eco_key(v);
 s:=jsonb_set(s,'{habitatZones}',zones||jsonb_build_array(z));return s-'ecoSuppressFauna';
end $$;

create or replace function hash3_private.eco_growth(state jsonb,at_time timestamptz)
returns jsonb language plpgsql set search_path='' as $$
#variable_conflict use_column
declare s jsonb:=hash3_private.eco_initialize(state,at_time);
begin
 s:=s||jsonb_build_object('territoryMilestone',greatest(coalesce((s->>'territoryMilestone')::int,0),jsonb_array_length(s->'terrain')/333));return hash3_private.eco_announce(s,at_time,'placements');
end $$;

create or replace function hash3_private.eco_before_command(state jsonb,action text,payload jsonb,at_time timestamptz)
returns jsonb language plpgsql set search_path='' as $$
#variable_conflict use_column
declare s jsonb:=hash3_private.eco_initialize(state,at_time);potential int:=0;sign text;pair jsonb;
begin
 if action='move' and s->>'territoryEnabled' is distinct from 'false' then
  select v into pair from jsonb_array_elements(s->'pairs') v where v->>lower(v->>'turn')=auth.uid()::text;
  if pair is not null and payload->>'x' is not null and payload->>'y' is not null then
   sign:=pair->>'turn';select count(*) into potential from jsonb_array_elements(hash3_private.scoring_figures(s||jsonb_build_object('cells',(s->'cells')||jsonb_build_array(jsonb_build_object('x',(payload->>'x')::int,'y',(payload->>'y')::int,'symbol',sign))), (payload->>'x')::int,(payload->>'y')::int,sign)) f where not (s->'forms') ? (f->>'id');
  end if;
  if (hash3_private.eco_ready(s) or coalesce((select sum((p->>'figures')::int) from jsonb_array_elements(s->'players') p),0)+potential>=(hash3_private.eco_config()->>'minFigures')::int) and hash3_private.eco_placements(s)+1>=(s->>'territoryNextPlacement')::int and jsonb_array_length(s->'territoryEvents')=0 and not hash3_private.eco_suspended(s,extract(epoch from at_time)*1000) then s:=s||jsonb_build_object('ecoSuppressFauna',true);end if;
 end if;
 return hash3_private.habitat_advance(s,at_time);
end $$;

DO $command_hooks$
declare definition text;needle text;
begin
 select pg_get_functiondef('hash3_private.command(text,jsonb)'::regprocedure) into definition;
 needle:=$needle$if action in ('move','expand') then s:=hash3_private.habitat_advance(s,now());update hash3_private.rooms set state=s where id=r.id;end if;$needle$;
 if position('eco_before_command' in definition)=0 then
  if position(needle in definition)=0 then raise exception 'Unexpected authoritative command baseline';end if;
  definition:=replace(definition,needle,$body$if action in ('move','expand') then s:=hash3_private.eco_before_command(s,action,payload,now());update hash3_private.rooms set state=s where id=r.id;end if;$body$);execute definition;
 end if;
 select pg_get_functiondef('hash3_private.legacy_command(text,jsonb)'::regprocedure) into definition;
 if position('eco_growth' in definition)=0 then
  needle:=$needle$if action='move' then s:=hash3_private.rodent_step(s,uid::text);end if;$needle$;
  if position(needle in definition)=0 then raise exception 'Unexpected placement baseline';end if;
  definition:=replace(definition,needle,needle||chr(10)||$body$if action='expand' then s:=hash3_private.eco_growth(s,now());end if;s:=s-'ecoSuppressFauna';$body$);execute definition;
 end if;
 select pg_get_functiondef('hash3_private.advance_state(jsonb,timestamptz)'::regprocedure) into definition;
 if position('eco_growth' in definition)=0 then
  needle:=$needle$if event->>'kind'='move' then s:=hash3_private.rodent_step(s,actor->>'id');end if;$needle$;
  if position(needle in definition)=0 then raise exception 'Unexpected autonomous placement baseline';end if;
  definition:=replace(definition,needle,needle||chr(10)||$body$if event->>'kind'='expand' then s:=hash3_private.eco_growth(s,at_time);end if;$body$);execute definition;
 end if;
 select pg_get_functiondef('hash3_private.territory_neutral(jsonb,jsonb)'::regprocedure) into definition;
 if position('eco_protected' in definition)=0 then definition:=replace(definition,$needle$where not cells ?$needle$,$body$where not hash3_private.eco_protected(s,extract(epoch from now())*1000) ? hash3_private.eco_key(t) and not cells ?$body$);execute definition;end if;
end $command_hooks$;

DO $privileges$
declare f record;
begin
 for f in select p.oid::regprocedure identity from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='hash3_private' and p.proname like 'eco_%' loop
  execute format('revoke all on function %s from public,anon,authenticated',f.identity);
 end loop;
end $privileges$;
